import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// --- Font Loader Pattern (Strict Adherence) ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:ital,wght@0,300;0,400;0,600;1,400&display=swap`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema Definition ---


export type EisenhowerMatrixProps = Record<string, any>;

// --- Helper Components ---

const AxisLabel: React.FC<{
  text: string;
  x: number;
  y: number;
  opacity: number;
  rotation?: number;
  align?: "center" | "left" | "right";
  fontFamily: string;
  color: string;
}> = ({ text, x, y, opacity, rotation = 0, align = "center", fontFamily, color }) => (
  <div
    style={{
      position: "absolute",
      left: x,
      top: y,
      transform: `translate(-50%, -50%) rotate(${rotation}deg)`,
      opacity,
      fontFamily,
      color,
      fontSize: 24,
      fontWeight: 600,
      textAlign: align,
      whiteSpace: "nowrap",
      textTransform: "uppercase",
      letterSpacing: "0.05em",
    }}
  >
    {text}
  </div>
);

const Quadrant: React.FC<{
  label: string; // The "Do", "Delegate" text
  subLabel: string; // Optional context
  x: number;
  y: number;
  width: number;
  height: number;
  delay: number;
  frame: number;
  fps: number;
  baseColor: string;
  highlightColor: string;
  borderColor: string;
  fontFamily: string;
}> = ({
  label,
  x,
  y,
  width,
  height,
  delay,
  frame,
  fps,
  baseColor,
  highlightColor,
  borderColor,
  fontFamily
}) => {
    // Activation Logic
    // Active window: Starts at 'delay'. 
    // We want a "focus" effect that happens when it first appears, then settles.
    
    const timeSinceStart = frame - delay;
    const enterProgress = spring({
      frame: timeSinceStart,
      fps,
      config: { damping: 20, stiffness: 100 },
    });

    const isActive = timeSinceStart >= 0;
    
    // Fade in text
    const textOpacity = interpolate(timeSinceStart, [0, 20], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    const textY = interpolate(enterProgress, [0, 1], [20, 0]);

    // Highlight logic: Flash bright, then settle to subtle
    // Flash happens at start (0-30 frames relative)
    const flashOpacity = interpolate(timeSinceStart, [0, 15, 60], [0, 0.25, 0.05], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp"
    });

    // Border thickness emphasis
    const borderScale = interpolate(timeSinceStart, [0, 10, 40], [1, 1.5, 1], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp"
    });

    if (!isActive) return null;

    return (
      <div
        style={{
          position: "absolute",
          left: x,
          top: y,
          width,
          height,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
        }}
      >
        {/* Background Highlight */}
        <div
            style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                backgroundColor: highlightColor,
                opacity: flashOpacity,
                borderRadius: 8,
                transform: `scale(${interpolate(enterProgress, [0, 1], [0.95, 1])})`,
            }}
        />

        {/* Text Content */}
        <div style={{ opacity: textOpacity, transform: `translateY(${textY}px)`, textAlign: 'center', zIndex: 2 }}>
            <h2
                style={{
                    fontFamily,
                    fontStyle: "italic",
                    fontSize: 48,
                    color: baseColor,
                    margin: 0,
                    fontWeight: 400,
                }}
            >
                {label}
            </h2>
        </div>
      </div>
    );
  };

// --- Main Component ---
const EisenhowerMatrix: React.FC<EisenhowerMatrixProps> = ({
  backgroundColor = "#3B3434",
  lineColor = "#ffffff",
  textColor = "#ffffff",
  highlightColor = "#ffffff",
  transparentBackground = false,
  gridThickness = 2,
  durationInSeconds = 10,
}) => {
  useFontLoader(["Playfair Display", "Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color Parsing
  const bgStyle = transparentBackground ? "transparent" : backgroundColor;

  // Layout Constants
  const gridSize = Math.min(width, height) * 0.6;
  const centerX = width / 2;
  const centerY = height / 2;
  const halfGrid = gridSize / 2;
  const quadrantSize = gridSize / 2;

  // Animation Timings
  const gridEntry = spring({
    frame,
    fps,
    config: { damping: 200, stiffness: 200, mass: 2 }, // Slow ease in
    durationInFrames: 60
  });
  
  const axisOpacity = interpolate(frame, [20, 50], [0, 1], { extrapolateRight: "clamp" });
  
  // Quadrant Delays (Clockwise from Top-Left)
  const q1Delay = 40; // TL
  const q2Delay = 70; // TR
  const q3Delay = 100; // BR
  const q4Delay = 130; // BL

  return (
    <AbsoluteFill style={{ backgroundColor: bgStyle }}>
      
      {/* --- Grid System --- */}
      <div
        style={{
          position: "absolute",
          left: centerX - halfGrid,
          top: centerY - halfGrid,
          width: gridSize,
          height: gridSize,
        }}
      >
        {/* Vertical Line */}
        <div
            style={{
                position: "absolute",
                left: "50%",
                top: 0,
                bottom: 0,
                width: gridThickness,
                backgroundColor: lineColor,
                transform: `scaleY(${gridEntry})`,
                opacity: interpolate(frame, [0, 30], [0, 1], { extrapolateRight: 'clamp'}),
                marginLeft: -gridThickness / 2,
            }}
        />
        {/* Horizontal Line */}
        <div
            style={{
                position: "absolute",
                top: "50%",
                left: 0,
                right: 0,
                height: gridThickness,
                backgroundColor: lineColor,
                transform: `scaleX(${gridEntry})`,
                opacity: interpolate(frame, [0, 30], [0, 1], { extrapolateRight: 'clamp'}),
                marginTop: -gridThickness / 2,
            }}
        />
        
        {/* --- Quadrants --- */}
        {/* TL: Do */}
        <Quadrant
            label="Do"
            subLabel="Urgent & Important"
            x={0}
            y={0}
            width={quadrantSize}
            height={quadrantSize}
            delay={q1Delay}
            frame={frame}
            fps={fps}
            baseColor={textColor}
            highlightColor={highlightColor}
            borderColor={lineColor}
            fontFamily="Playfair Display"
        />
         {/* TR: Do Later */}
         <Quadrant
            label="Do Later"
            subLabel="Not Urgent & Important"
            x={quadrantSize}
            y={0}
            width={quadrantSize}
            height={quadrantSize}
            delay={q2Delay}
            frame={frame}
            fps={fps}
            baseColor={textColor}
            highlightColor={highlightColor}
            borderColor={lineColor}
            fontFamily="Playfair Display"
        />
        {/* BR: Delete */}
        <Quadrant
            label="Delete"
            subLabel="Not Urgent & Not Important"
            x={quadrantSize}
            y={quadrantSize}
            width={quadrantSize}
            height={quadrantSize}
            delay={q3Delay} // Clockwise sequence means BR is 3rd
            frame={frame}
            fps={fps}
            baseColor={textColor}
            highlightColor={highlightColor}
            borderColor={lineColor}
            fontFamily="Playfair Display"
        />
         {/* BL: Delegate */}
         <Quadrant
            label="Delegate"
            subLabel="Urgent & Not Important"
            x={0}
            y={quadrantSize}
            width={quadrantSize}
            height={quadrantSize}
            delay={q4Delay} // Clockwise sequence means BL is 4th
            frame={frame}
            fps={fps}
            baseColor={textColor}
            highlightColor={highlightColor}
            borderColor={lineColor}
            fontFamily="Playfair Display"
        />
      </div>

      {/* --- Axis Labels --- */}
      {/* Left Axis: Important / Not Important */}
      <AxisLabel
        text="Important"
        x={centerX - halfGrid - 40}
        y={centerY - halfGrid / 2}
        opacity={axisOpacity}
        rotation={-90}
        fontFamily="Inter"
        color={textColor}
      />
      <AxisLabel
        text="Not Important"
        x={centerX - halfGrid - 40}
        y={centerY + halfGrid / 2}
        opacity={axisOpacity}
        rotation={-90}
        fontFamily="Inter"
        color={textColor}
      />

      {/* Bottom Axis: Urgent / Not Urgent */}
      <AxisLabel
        text="Urgent"
        x={centerX - halfGrid / 2}
        y={centerY + halfGrid + 40}
        opacity={axisOpacity}
        fontFamily="Inter"
        color={textColor}
      />
      <AxisLabel
        text="Not Urgent"
        x={centerX + halfGrid / 2}
        y={centerY + halfGrid + 40}
        opacity={axisOpacity}
        fontFamily="Inter"
        color={textColor}
      />

    </AbsoluteFill>
  );
};

export default EisenhowerMatrix;